def is_balanced(text: str) -> bool:
    """
    Check whether all parentheses in `text` are balanced.

    Supports (), [], and {}. Non-bracket characters are ignored.
    """
    pairs = {')': '(', ']': '[', '}': '{'}
    stack = []
    for ch in text:
        if ch in '([{':
            stack.append(ch)
        elif ch in pairs:
            if not stack or stack.pop() != pairs[ch]:
                return False
    return not stack


assert is_balanced("a(b[c]{d}e)f") is True
assert is_balanced("([)]") is False
assert is_balanced("(((") is False
assert is_balanced("") is True
